static size_t spatial_bucket(int32_t x, int32_t y) { return (((uint32_t)x*73856093u)^((uint32_t)y*19349663u))%SPATIAL_BUCKETS; }
void spatial_clear(SpatialHash *h) { for(size_t i=0;i<SPATIAL_BUCKETS;i++)h->heads[i]=-1;h->n=0; }
SpatialHash spatial_init(float cell) { assert(cell>0);SpatialHash h={.cell=cell};spatial_clear(&h);return h; }
size_t spatial_insert(SpatialHash *h, float x, float y) {
    if(h->n==SPATIAL_MAX)return SIZE_MAX;
    size_t id=h->n++,b=spatial_bucket(spatial_cell(h,x),spatial_cell(h,y));
    h->xs[id]=x;h->ys[id]=y;h->next[id]=h->heads[b];h->heads[b]=(int)id;return id;
