    for(int64_t cy=y0;cy<=y1;cy++)for(int64_t cx=x0;cx<=x1;cx++) {
        for(int id=h->heads[spatial_bucket((int32_t)cx,(int32_t)cy)];id>=0;id=h->next[id]) {
