            case SWAP:{if(n<2)return vm_error(STACK_UNDERFLOW);int32_t v=stack[n-1];stack[n-1]=stack[n-2];stack[n-2]=v;break;}
            case JZ:if(!n)return vm_error(STACK_UNDERFLOW);if(stack[--n]!=0)break;/* fall through */
            case JMP:if(op.arg<0||(size_t)op.arg>=length)return vm_error(BAD_JUMP);pc=(size_t)op.arg;break;
            case HALT:if(!n)return vm_error(STACK_UNDERFLOW);return (Result){VM_OK,stack[n-1]};
            default:return vm_error(NO_HALT);
        }
    }
}

