#include <assert.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <limits.h>

/* grid borrows height NUL-terminated rows of equal width. out is caller-owned
   and written only on a hit. Direction and origin must be finite, max_dist>=0.
   Exact corner ties follow the original drill: step y, then x at the same t. */
typedef struct { size_t col,row;double dist; } Hit;
bool raycast(const char *const *grid, size_t height, double ox, double oy, double dx, double dy, double max_dist, Hit *out) {
    if(!height||max_dist<0||!isfinite(ox)||!isfinite(oy)||!isfinite(dx)||!isfinite(dy))return false;
    size_t width=strlen(grid[0]);if(!width||ox<0||oy<0||ox>=(double)width||oy>=(double)height)return false;
    double length=hypot(dx,dy);if(length==0||!isfinite(length))return false;double ux=dx/length,uy=dy/length;
    int64_t x=(int64_t)floor(ox),y=(int64_t)floor(oy);if(grid[y][x]=='#'){*out=(Hit){(size_t)x,(size_t)y,0};return true;}
    int sx=ux>0?1:-1,sy=uy>0?1:-1;double tx=ux==0?INFINITY:fabs(1/ux),ty=uy==0?INFINITY:fabs(1/uy);
    double mx=ux==0?INFINITY:(ux>0?x+1-ox:ox-x)*tx,my=uy==0?INFINITY:(uy>0?y+1-oy:oy-y)*ty;
    for(;;){double distance;if(mx<my){distance=mx;x+=sx;mx+=tx;}else{distance=my;y+=sy;my+=ty;}
        if(distance>max_dist||x<0||y<0||(uint64_t)x>=width||(uint64_t)y>=height)return false;
        if(grid[y][x]=='#'){*out=(Hit){(size_t)x,(size_t)y,distance};return true;}
    }
}

